import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {test} from 'node:test';import {decodeLzma2} from '../lzma-decoder.mjs';
const root=new URL('./',import.meta.url),c=vm.createContext({});vm.runInContext(fs.readFileSync(new URL('../source/archive.js',root),'utf8'),c);c.ArchiveReader=vm.runInContext('ArchiveReader',c);const cases=JSON.parse(fs.readFileSync(new URL('lzma2-cases.json',root)));const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
for(const item of cases)test('LZMA2 Python reference '+item.name,()=>{const data=fs.readFileSync(new URL('lzma2/'+item.name+'.raw',root)),props=Uint8Array.of(item.properties);assert.equal(sha(c.decodeLzma2(data,props,item.size)),item.sha256);assert.equal(sha(decodeLzma2(data,props,item.size)),item.sha256);});
test('LZMA2 stored data in 7z matches prior decoder',()=>{const old=vm.createContext({});vm.runInContext(fs.readFileSync(new URL('references/lzma1-lzma2-sdk.js',root),'utf8'),old);const data=fs.readFileSync(new URL('archives/lzma2-raw.7z',root));assert.equal(sha(c.readSevenZip(data)),sha(old.readSevenZip(data)));});
test('LZMA2 rejects missing dictionary/state initialization and invalid properties',()=>{for(const bytes of [[2,0,0,1,0],[128,0,0,0,4,0,0,0,0,0,0],[3,0,0,0]])assert.throws(()=>c.decodeLzma2(Uint8Array.from(bytes),Uint8Array.of(0),1),/Data/);assert.throws(()=>c.decodeLzma2(new Uint8Array([0]),new Uint8Array([41]),0),/Prop/);const b=fs.readFileSync(new URL('lzma2/state-reset.raw',root));const p=Buffer.from(b);p[5]=224;assert.throws(()=>c.decodeLzma2(p,Uint8Array.of(16),32768),/Prop/);});
test('LZMA2 rejects truncation, output-size mismatch, trailing bytes and missing end',()=>{const b=fs.readFileSync(new URL('lzma2/multichunk.raw',root)),n=cases.find(x=>x.name==='multichunk').size;assert.throws(()=>c.decodeLzma2(b.subarray(0,15),Uint8Array.of(16),n));assert.throws(()=>c.decodeLzma2(b,Uint8Array.of(16),n-1));assert.throws(()=>c.decodeLzma2(Buffer.concat([b,Buffer.from([0])]),Uint8Array.of(16),n),/Data/);assert.throws(()=>c.decodeLzma2(b.subarray(0,-1),Uint8Array.of(16),n),/EOF/);});
test('short error causes distinguish truncation, size, method, file count and format',()=>{assert.throws(()=>c.readSevenZip(new Uint8Array(12)),/EOF/);assert.throws(()=>c.decodeLzma2(new Uint8Array([0]),Uint8Array.of(0),17<<20),/Size/);for(const [name,reason]of [['multiple.7z','Multi'],['empty.7z','Empty'],['stored.7z','Codec']]){const b=fs.readFileSync(new URL('archives/'+name,root));assert.throws(()=>c.readSevenZip(b),new RegExp(reason));}assert.throws(()=>c.readStreams(new c.ArchiveReader(new Uint8Array([0]))),/Fmt/);});
